/**
 * Generate realistic LiDAR point cloud data
 * Simulates Velodyne VLS-128 sensor with configurable FOV and noise
 */

export function generateLiDARPointCloud(config) {
  const {
    fov = { vertical: [25, -25], horizontal: 360 },
    numPoints = 50000,
    scene = 'urban',
    calibrationDrift = { pitch: 0, yaw: 0, roll: 0 },
    voxelSize = 0.05,
    noiseLevel = 0.02
  } = config

  const points = []
  const colors = []

  // Convert FOV to radians
  const vertMin = (fov.vertical[1] * Math.PI) / 180
  const vertMax = (fov.vertical[0] * Math.PI) / 180
  const horizSpan = (fov.horizontal * Math.PI) / 180

  // Generate ground plane
  for (let i = 0; i < numPoints * 0.3; i++) {
    const angle = Math.random() * horizSpan - horizSpan / 2
    const distance = 5 + Math.random() * 45

    // Apply calibration drift (rotation matrix)
    const driftYaw = (calibrationDrift.yaw * Math.PI) / 180
    const driftPitch = (calibrationDrift.pitch * Math.PI) / 180

    const adjustedAngle = angle + driftYaw
    const verticalAngle = vertMin + Math.random() * 0.1 + driftPitch

    const x = distance * Math.cos(verticalAngle) * Math.sin(adjustedAngle)
    const y = distance * Math.sin(verticalAngle) - 1.5 // ground offset
    const z = distance * Math.cos(verticalAngle) * Math.cos(adjustedAngle)

    // Add noise
    const noise = () => (Math.random() - 0.5) * noiseLevel
    points.push(x + noise(), y + noise(), z + noise())

    // Ground color (gray)
    colors.push(0.3, 0.3, 0.3)
  }

  // Generate buildings/obstacles
  for (let i = 0; i < numPoints * 0.4; i++) {
    const angle = Math.random() * horizSpan - horizSpan / 2
    const distance = 10 + Math.random() * 30
    const height = Math.random() * 8 - 1.5

    const driftYaw = (calibrationDrift.yaw * Math.PI) / 180
    const driftPitch = (calibrationDrift.pitch * Math.PI) / 180

    const adjustedAngle = angle + driftYaw
    const verticalAngle = Math.atan2(height, distance) + driftPitch

    if (verticalAngle >= vertMin && verticalAngle <= vertMax) {
      const x = distance * Math.sin(adjustedAngle)
      const y = height
      const z = distance * Math.cos(adjustedAngle)

      const noise = () => (Math.random() - 0.5) * noiseLevel
      points.push(x + noise(), y + noise(), z + noise())

      // Building color (light gray/white)
      colors.push(0.6, 0.6, 0.65)
    }
  }

  // Generate vehicles
  for (let i = 0; i < numPoints * 0.2; i++) {
    const angle = (Math.random() - 0.5) * horizSpan
    const distance = 8 + Math.random() * 25
    const height = Math.random() * 2 - 1.5

    const driftYaw = (calibrationDrift.yaw * Math.PI) / 180
    const driftPitch = (calibrationDrift.pitch * Math.PI) / 180

    const adjustedAngle = angle + driftYaw
    const verticalAngle = Math.atan2(height, distance) + driftPitch

    if (verticalAngle >= vertMin && verticalAngle <= vertMax) {
      const x = distance * Math.sin(adjustedAngle)
      const y = height
      const z = distance * Math.cos(adjustedAngle)

      const noise = () => (Math.random() - 0.5) * noiseLevel
      points.push(x + noise(), y + noise(), z + noise())

      // Vehicle color (blue-ish)
      colors.push(0.2, 0.4, 0.8)
    }
  }

  // Generate pedestrians
  for (let i = 0; i < numPoints * 0.1; i++) {
    const angle = (Math.random() - 0.5) * horizSpan
    const distance = 3 + Math.random() * 15
    const height = Math.random() * 1.8 - 1.5

    const driftYaw = (calibrationDrift.yaw * Math.PI) / 180
    const driftPitch = (calibrationDrift.pitch * Math.PI) / 180

    const adjustedAngle = angle + driftYaw
    const verticalAngle = Math.atan2(height, distance) + driftPitch

    if (verticalAngle >= vertMin && verticalAngle <= vertMax) {
      const x = distance * Math.sin(adjustedAngle)
      const y = height
      const z = distance * Math.cos(adjustedAngle)

      const noise = () => (Math.random() - 0.5) * noiseLevel
      points.push(x + noise(), y + noise(), z + noise())

      // Pedestrian color (yellow/orange)
      colors.push(1.0, 0.6, 0.0)
    }
  }

  return {
    positions: new Float32Array(points),
    colors: new Float32Array(colors),
    count: points.length / 3
  }
}

/**
 * Apply voxel grid filtering (downsampling)
 */
export function applyVoxelGridFilter(pointCloud, voxelSize) {
  const voxelMap = new Map()
  const positions = pointCloud.positions
  const colors = pointCloud.colors

  for (let i = 0; i < positions.length; i += 3) {
    const x = positions[i]
    const y = positions[i + 1]
    const z = positions[i + 2]

    // Compute voxel key
    const vx = Math.floor(x / voxelSize)
    const vy = Math.floor(y / voxelSize)
    const vz = Math.floor(z / voxelSize)
    const key = `${vx},${vy},${vz}`

    if (!voxelMap.has(key)) {
      voxelMap.set(key, {
        x: 0, y: 0, z: 0,
        r: 0, g: 0, b: 0,
        count: 0
      })
    }

    const voxel = voxelMap.get(key)
    voxel.x += x
    voxel.y += y
    voxel.z += z
    voxel.r += colors[i]
    voxel.g += colors[i + 1]
    voxel.b += colors[i + 2]
    voxel.count++
  }

  // Average points in each voxel
  const filteredPositions = []
  const filteredColors = []

  for (const voxel of voxelMap.values()) {
    filteredPositions.push(
      voxel.x / voxel.count,
      voxel.y / voxel.count,
      voxel.z / voxel.count
    )
    filteredColors.push(
      voxel.r / voxel.count,
      voxel.g / voxel.count,
      voxel.b / voxel.count
    )
  }

  return {
    positions: new Float32Array(filteredPositions),
    colors: new Float32Array(filteredColors),
    count: filteredPositions.length / 3
  }
}
