import React, { useState } from 'react'
import { useStore } from '../store/useStore'
import { COLORS } from '../utils/colors'
import { QUERY_SUGGESTIONS } from '../data/datasets'

export default function QueryPanel() {
  const { queryText, setQuery, executeQuery } = useStore()
  const [showSuggestions, setShowSuggestions] = useState(false)

  const handleQuerySubmit = (e) => {
    e.preventDefault()
    executeQuery()
    setShowSuggestions(false)
  }

  return (
    <div style={styles.panel}>
      <div style={styles.header}>
        <h2 style={styles.title}>Semantic Query</h2>
        <div style={styles.badge}>Live</div>
      </div>

      <form onSubmit={handleQuerySubmit} style={styles.form}>
        <div style={styles.inputWrapper}>
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" style={styles.icon}>
            <circle cx="8" cy="8" r="6" stroke={COLORS.textMuted} strokeWidth="2" />
            <path d="M12.5 12.5l5 5" stroke={COLORS.textMuted} strokeWidth="2" strokeLinecap="round" />
          </svg>
          <input
            type="text"
            value={queryText}
            onChange={(e) => {
              setQuery(e.target.value)
              setShowSuggestions(e.target.value.length > 0)
            }}
            onFocus={() => setShowSuggestions(true)}
            placeholder="rain + LiDAR v2.3+ + urban >500 peds/km²"
            style={styles.input}
          />
        </div>
        <button type="submit" style={styles.searchButton}>
          Search
        </button>
      </form>

      {showSuggestions && (
        <div style={styles.suggestions}>
          <div style={styles.suggestionsHeader}>Suggested Queries</div>
          {QUERY_SUGGESTIONS.map((suggestion, idx) => (
            <button
              key={idx}
              style={styles.suggestionItem}
              onClick={() => {
                setQuery(suggestion)
                setShowSuggestions(false)
              }}
            >
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                <path
                  d="M8 2L3 7h4v6h2V7h4L8 2z"
                  fill={COLORS.textMuted}
                />
              </svg>
              {suggestion}
            </button>
          ))}
        </div>
      )}

      <div style={styles.filters}>
        <h3 style={styles.filterTitle}>Active Filters</h3>
        <div style={styles.filterList}>
          <FilterTag label="Location: Turin vs Munich" color={COLORS.accent} />
          <FilterTag label="Weather: Mixed" color={COLORS.warning} />
          <FilterTag label="Sensor: VLS-128" color={COLORS.primary} />
        </div>
      </div>

      <div style={styles.stats}>
        <StatCard label="Datasets" value="4" />
        <StatCard label="Frames" value="67.5K" />
        <StatCard label="Drift Score" value="2.3" color={COLORS.drift} />
      </div>
    </div>
  )
}

function FilterTag({ label, color }) {
  return (
    <div style={{...styles.filterTag, borderColor: color}}>
      <div style={{...styles.filterDot, background: color}} />
      <span>{label}</span>
      <button style={styles.filterRemove}>×</button>
    </div>
  )
}

function StatCard({ label, value, color = COLORS.match }) {
  return (
    <div style={styles.statCard}>
      <div style={{...styles.statValue, color}}>{value}</div>
      <div style={styles.statLabel}>{label}</div>
    </div>
  )
}

