import React, { useRef, useEffect, useState } from 'react'
import { useStore } from '../store/useStore'
import { COLORS } from '../utils/colors'
import { DATASET_VERSIONS } from '../data/datasets'

export default function TimelineGraph() {
  const canvasRef = useRef(null)
  const { leftDataset, rightDataset, selectVersion } = useStore()
  const [hoveredNode, setHoveredNode] = useState(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    const ctx = canvas.getContext('2d')
    const width = canvas.width = canvas.offsetWidth * window.devicePixelRatio
    const height = canvas.height = canvas.offsetHeight * window.devicePixelRatio
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio)

    // Draw timeline
    drawTimeline(ctx, canvas.offsetWidth, canvas.offsetHeight)
  }, [leftDataset, rightDataset, hoveredNode])

  const drawTimeline = (ctx, width, height) => {
    ctx.clearRect(0, 0, width, height)

    // Timeline configuration
    const padding = 60
    const timelineY = height / 2
    const nodeRadius = 8
    const branchOffset = 40

    // Draw branches
    const turinY = timelineY - branchOffset
    const munichY = timelineY + branchOffset

    // Turin branch
    drawBranch(ctx, DATASET_VERSIONS.turin, turinY, padding, width - padding, COLORS.match, 'turin')

    // Munich branch
    drawBranch(ctx, DATASET_VERSIONS.munich, munichY, padding, width - padding, COLORS.accent, 'munich')

    // Draw merge/comparison lines
    const turinLatest = DATASET_VERSIONS.turin[DATASET_VERSIONS.turin.length - 1]
    const munichLatest = DATASET_VERSIONS.munich[DATASET_VERSIONS.munich.length - 1]

    ctx.setLineDash([5, 5])
    ctx.strokeStyle = COLORS.primary
    ctx.lineWidth = 2
    ctx.beginPath()
    ctx.moveTo(width - padding - 100, turinY)
    ctx.lineTo(width - padding - 100, munichY)
    ctx.stroke()
    ctx.setLineDash([])

    // Draw comparison label
    ctx.fillStyle = COLORS.primary
    ctx.font = '10px sans-serif'
    ctx.fillText('DIFF', width - padding - 115, timelineY)
  }

  const drawBranch = (ctx, versions, y, startX, endX, color, location) => {
    const spacing = (endX - startX) / (versions.length + 1)

    // Draw branch line
    ctx.strokeStyle = `${color}40`
    ctx.lineWidth = 2
    ctx.beginPath()
    ctx.moveTo(startX, y)
    ctx.lineTo(endX, y)
    ctx.stroke()

    // Draw version nodes
    versions.forEach((version, index) => {
      const x = startX + spacing * (index + 1)
      const isSelected = version.id === leftDataset?.id || version.id === rightDataset?.id
      const isHovered = hoveredNode === version.id

      // Node circle
      ctx.beginPath()
      ctx.arc(x, y, isSelected ? 10 : 8, 0, Math.PI * 2)
      ctx.fillStyle = isSelected ? color : `${color}60`
      ctx.fill()

      if (isSelected) {
        ctx.strokeStyle = color
        ctx.lineWidth = 2
        ctx.stroke()
      }

      // Commit hash
      ctx.fillStyle = COLORS.textMuted
      ctx.font = '9px monospace'
      ctx.textAlign = 'center'
      ctx.fillText(version.commit, x, y + 25)

      // Version label
      ctx.fillStyle = COLORS.text
      ctx.font = 'bold 10px sans-serif'
      ctx.fillText(version.version, x, y - 15)

      // Store node position for interaction
      if (isHovered) {
        drawTooltip(ctx, version, x, y)
      }
    })

    // Draw branch label
    ctx.fillStyle = color
    ctx.font = 'bold 12px sans-serif'
    ctx.textAlign = 'left'
    ctx.fillText(location.toUpperCase(), startX, y - 55)
  }

  const drawTooltip = (ctx, version, x, y) => {
    const tooltipWidth = 200
    const tooltipHeight = 80
    const tooltipX = x - tooltipWidth / 2
    const tooltipY = y - tooltipHeight - 40

    // Tooltip background
    ctx.fillStyle = COLORS.card
    ctx.strokeStyle = COLORS.cardBorder
    ctx.lineWidth = 1
    roundRect(ctx, tooltipX, tooltipY, tooltipWidth, tooltipHeight, 8)
    ctx.fill()
    ctx.stroke()

    // Tooltip content
    ctx.fillStyle = COLORS.text
    ctx.font = 'bold 11px sans-serif'
    ctx.textAlign = 'left'
    ctx.fillText(version.version, tooltipX + 10, tooltipY + 20)

    ctx.fillStyle = COLORS.textMuted
    ctx.font = '9px sans-serif'
    ctx.fillText(version.date, tooltipX + 10, tooltipY + 35)
    ctx.fillText(version.message, tooltipX + 10, tooltipY + 50)
    ctx.fillText(`${version.weather} • ${version.stats.frames} frames`, tooltipX + 10, tooltipY + 65)
  }

  const handleCanvasClick = (e) => {
    const canvas = canvasRef.current
    const rect = canvas.getBoundingClientRect()
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top

    // Simple hit detection (would be more sophisticated in production)
    const padding = 60
    const width = canvas.offsetWidth
    const timelineY = canvas.offsetHeight / 2
    const branchOffset = 40

    // Check Turin nodes
    const turinY = timelineY - branchOffset
    const turinSpacing = (width - padding * 2) / (DATASET_VERSIONS.turin.length + 1)
    DATASET_VERSIONS.turin.forEach((version, index) => {
      const nodeX = padding + turinSpacing * (index + 1)
      const distance = Math.sqrt((x - nodeX) ** 2 + (y - turinY) ** 2)
      if (distance < 12) {
        selectVersion('turin', version.id)
      }
    })

    // Check Munich nodes
    const munichY = timelineY + branchOffset
    const munichSpacing = (width - padding * 2) / (DATASET_VERSIONS.munich.length + 1)
    DATASET_VERSIONS.munich.forEach((version, index) => {
      const nodeX = padding + munichSpacing * (index + 1)
      const distance = Math.sqrt((x - nodeX) ** 2 + (y - munichY) ** 2)
      if (distance < 12) {
        selectVersion('munich', version.id)
      }
    })
  }

  const handleCanvasHover = (e) => {
    const canvas = canvasRef.current
    const rect = canvas.getBoundingClientRect()
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top

    const padding = 60
    const width = canvas.offsetWidth
    const timelineY = canvas.offsetHeight / 2
    const branchOffset = 40

    let foundHover = null

    // Check Turin nodes
    const turinY = timelineY - branchOffset
    const turinSpacing = (width - padding * 2) / (DATASET_VERSIONS.turin.length + 1)
    DATASET_VERSIONS.turin.forEach((version, index) => {
      const nodeX = padding + turinSpacing * (index + 1)
      const distance = Math.sqrt((x - nodeX) ** 2 + (y - turinY) ** 2)
      if (distance < 12) {
        foundHover = version.id
      }
    })

    // Check Munich nodes
    const munichY = timelineY + branchOffset
    const munichSpacing = (width - padding * 2) / (DATASET_VERSIONS.munich.length + 1)
    DATASET_VERSIONS.munich.forEach((version, index) => {
      const nodeX = padding + munichSpacing * (index + 1)
      const distance = Math.sqrt((x - nodeX) ** 2 + (y - munichY) ** 2)
      if (distance < 12) {
        foundHover = version.id
      }
    })

    setHoveredNode(foundHover)
    canvas.style.cursor = foundHover ? 'pointer' : 'default'
  }

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h3 style={styles.title}>Dataset Timeline</h3>
        <div style={styles.legend}>
          <LegendItem color={COLORS.match} label="Turin" />
          <LegendItem color={COLORS.accent} label="Munich" />
        </div>
      </div>
      <canvas
        ref={canvasRef}
        style={styles.canvas}
        onClick={handleCanvasClick}
        onMouseMove={handleCanvasHover}
        onMouseLeave={() => setHoveredNode(null)}
      />
    </div>
  )
}

function LegendItem({ color, label }) {
  return (
    <div style={styles.legendItem}>
      <div style={{...styles.legendDot, background: color}} />
      <span style={styles.legendLabel}>{label}</span>
    </div>
  )
}

function roundRect(ctx, x, y, width, height, radius) {
  ctx.beginPath()
  ctx.moveTo(x + radius, y)
  ctx.lineTo(x + width - radius, y)
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius)
  ctx.lineTo(x + width, y + height - radius)
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height)
  ctx.lineTo(x + radius, y + height)
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius)
  ctx.lineTo(x, y + radius)
  ctx.quadraticCurveTo(x, y, x + radius, y)
  ctx.closePath()
}

const styles = {
  container: {
    height: '200px',
    background: COLORS.card,
    backdropFilter: 'blur(20px)',
    borderTop: `1px solid ${COLORS.cardBorder}`,
    display: 'flex',
    flexDirection: 'column',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '0.75rem 2rem',
    borderBottom: `1px solid ${COLORS.cardBorder}`,
  },
  title: {
    fontSize: '0.875rem',
    fontWeight: '600',
    color: COLORS.text,
    margin: 0,
  },
  legend: {
    display: 'flex',
    gap: '1.5rem',
  },
  legendItem: {
    display: 'flex',
    alignItems: 'center',
    gap: '0.5rem',
  },
  legendDot: {
    width: '8px',
    height: '8px',
    borderRadius: '50%',
  },
  legendLabel: {
    fontSize: '0.75rem',
    color: COLORS.textMuted,
  },
  canvas: {
    flex: 1,
    width: '100%',
    cursor: 'default',
  },
}
