import { create } from 'zustand'
import { DATASET_VERSIONS } from '../data/datasets'
import { analyzeDrift } from '../algorithms/calibrationDrift'

export const useStore = create((set, get) => ({
  // Selected datasets for comparison
  leftDataset: DATASET_VERSIONS.turin[1],
  rightDataset: DATASET_VERSIONS.munich[0],

  // Timeline state
  selectedBranch: 'turin',
  timelineZoom: 1.0,

  // Query state
  queryText: '',
  queryResults: null,

  // Drift analysis
  driftAnalysis: null,

  // UI state
  showDriftOverlay: true,
  activePanel: 'diff', // 'diff', 'metadata', 'timeline'

  // Actions
  setLeftDataset: (dataset) => {
    set({ leftDataset: dataset })
    get().updateDriftAnalysis()
  },

  setRightDataset: (dataset) => {
    set({ rightDataset: dataset })
    get().updateDriftAnalysis()
  },

  setQuery: (text) => set({ queryText: text }),

  executeQuery: () => {
    const { queryText, leftDataset, rightDataset } = get()
    // Simple query matching (in real system, would use semantic search)
    const results = {
      matches: [],
      filters: parseQuery(queryText)
    }
    set({ queryResults: results })
  },

  updateDriftAnalysis: () => {
    const { leftDataset, rightDataset } = get()
    if (leftDataset && rightDataset) {
      const analysis = analyzeDrift(leftDataset, rightDataset)
      set({ driftAnalysis: analysis })
    }
  },

  toggleDriftOverlay: () => set((state) => ({ showDriftOverlay: !state.showDriftOverlay })),

  setActivePanel: (panel) => set({ activePanel: panel }),

  selectVersion: (location, versionId) => {
    const dataset = DATASET_VERSIONS[location].find(d => d.id === versionId)
    if (dataset) {
      if (location === 'turin') {
        get().setLeftDataset(dataset)
      } else {
        get().setRightDataset(dataset)
      }
    }
  }
}))

function parseQuery(query) {
  const filters = {
    weather: [],
    traffic: [],
    preprocessing: {},
    sensors: {}
  }

  const lowerQuery = query.toLowerCase()

  if (lowerQuery.includes('rain')) filters.weather.push('rain')
  if (lowerQuery.includes('fog')) filters.weather.push('fog')
  if (lowerQuery.includes('heavy traffic')) filters.traffic.push('heavy')
  if (lowerQuery.includes('urban')) filters.environment = 'urban'

  return filters
}

// Initialize drift analysis on load
setTimeout(() => {
  useStore.getState().updateDriftAnalysis()
}, 0)
