/**
 * Calculate calibration drift between two sensor configurations
 * Returns drift in pitch, yaw, roll (degrees)
 */

export function calculateCalibrationDrift(sensor1, sensor2) {
  const fov1 = sensor1.lidarFOV
  const fov2 = sensor2.lidarFOV

  // Calculate vertical FOV drift (pitch)
  const verticalCenter1 = (fov1.vertical[0] + fov1.vertical[1]) / 2
  const verticalCenter2 = (fov2.vertical[0] + fov2.vertical[1]) / 2
  const pitchDrift = verticalCenter2 - verticalCenter1

  // Calculate FOV span drift
  const span1 = fov1.vertical[0] - fov1.vertical[1]
  const span2 = fov2.vertical[0] - fov2.vertical[1]
  const spanDrift = span2 - span1

  // Estimate yaw drift (simplified - would use IMU data in real system)
  const yawDrift = Math.random() * 0.5 - 0.25

  return {
    pitch: pitchDrift,
    yaw: yawDrift,
    roll: spanDrift * 0.1, // simplified correlation
    magnitude: Math.sqrt(pitchDrift ** 2 + yawDrift ** 2 + spanDrift ** 2),
    isCritical: Math.abs(pitchDrift) > 0.5 || Math.abs(spanDrift) > 1.0
  }
}

/**
 * Calculate environmental drift (weather, lighting, traffic)
 */
export function calculateEnvironmentalDrift(env1, env2) {
  const trafficMap = { 'Medium': 1, 'Heavy': 2, 'Very Heavy': 3 }
  const lightingMap = { 'Daylight': 3, 'Overcast': 2, 'Low Visibility': 1 }

  const trafficDiff = Math.abs(trafficMap[env1.traffic] - trafficMap[env2.traffic])
  const lightingDiff = Math.abs(lightingMap[env1.lighting] - lightingMap[env2.lighting])
  const pedestrianDiff = Math.abs(env1.pedestrians - env2.pedestrians)
  const tempDiff = Math.abs(env1.temperature - env2.temperature)

  return {
    traffic: trafficDiff,
    lighting: lightingDiff,
    pedestrians: pedestrianDiff,
    temperature: tempDiff,
    overall: (trafficDiff + lightingDiff + pedestrianDiff / 100 + tempDiff / 10) / 4,
    isCritical: trafficDiff >= 2 || lightingDiff >= 2 || pedestrianDiff > 300
  }
}

/**
 * Calculate preprocessing pipeline drift
 */
export function calculatePreprocessingDrift(preproc1, preproc2) {
  const voxelDiff = Math.abs(preproc1.lidarVoxelSize - preproc2.lidarVoxelSize)
  const filterDiff = preproc1.noiseFilter !== preproc2.noiseFilter ? 1 : 0
  const groundDiff = preproc1.groundRemoval !== preproc2.groundRemoval ? 1 : 0

  return {
    voxelSize: voxelDiff,
    noiseFilter: filterDiff,
    groundRemoval: groundDiff,
    overall: (voxelDiff * 10 + filterDiff + groundDiff) / 3,
    isCritical: voxelDiff > 0.02 || filterDiff > 0 || groundDiff > 0,
    changes: [
      voxelDiff > 0 && `Voxel size: ${preproc1.lidarVoxelSize} → ${preproc2.lidarVoxelSize}`,
      filterDiff && `Noise filter: ${preproc1.noiseFilter} → ${preproc2.noiseFilter}`,
      groundDiff && `Ground removal: ${preproc1.groundRemoval} → ${preproc2.groundRemoval}`
    ].filter(Boolean)
  }
}

/**
 * Comprehensive drift analysis
 */
export function analyzeDrift(dataset1, dataset2) {
  const calibration = calculateCalibrationDrift(dataset1.sensors, dataset2.sensors)
  const environment = calculateEnvironmentalDrift(dataset1.environment, dataset2.environment)
  const preprocessing = calculatePreprocessingDrift(dataset1.preprocessing, dataset2.preprocessing)

  const overallDriftScore = (
    calibration.magnitude * 2 +
    environment.overall +
    preprocessing.overall
  ) / 4

  return {
    calibration,
    environment,
    preprocessing,
    overallScore: overallDriftScore,
    riskLevel: overallDriftScore > 2 ? 'high' : overallDriftScore > 1 ? 'medium' : 'low',
    summary: generateDriftSummary(calibration, environment, preprocessing)
  }
}

function generateDriftSummary(cal, env, prep) {
  const issues = []

  if (cal.isCritical) {
    issues.push(`⚠️ Critical sensor calibration drift detected (${cal.magnitude.toFixed(2)}°)`)
  }
  if (env.isCritical) {
    issues.push(`🌍 Significant environmental differences detected`)
  }
  if (prep.isCritical) {
    issues.push(`⚙️ Preprocessing pipeline mismatch: ${prep.changes.join(', ')}`)
  }

  if (issues.length === 0) {
    return '✅ Datasets are well-aligned with minimal drift'
  }

  return issues.join('\n')
}
