function LiDARPointCloud({ dataset, color }) {
  const meshRef = useRef()

  const pointCloud = useMemo(() => {
    // Calculate calibration drift from FOV
    const fov = dataset.sensors.lidarFOV
    const verticalCenter = (fov.vertical[0] + fov.vertical[1]) / 2
    const driftPitch = 25 - Math.abs(verticalCenter) // drift from ideal 0°

    const cloud = generateLiDARPointCloud({
      fov: dataset.sensors.lidarFOV,
      numPoints: 30000,
      scene: 'urban',
      calibrationDrift: {
        pitch: driftPitch * 0.3,
        yaw: Math.random() * 0.5 - 0.25,
        roll: 0
      },
      voxelSize: dataset.preprocessing.lidarVoxelSize,
      noiseLevel: 0.02
    })

    return applyVoxelGridFilter(cloud, dataset.preprocessing.lidarVoxelSize)
  }, [dataset])

  // Gentle rotation animation
  useFrame((state) => {
    if (meshRef.current) {
      meshRef.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.1) * 0.05
    }
  })

  return (
    <points ref={meshRef}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={pointCloud.count}
          array={pointCloud.positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={pointCloud.count}
          array={pointCloud.colors}
          itemSize={3}
        />
      </bufferGeometry>
      <pointsMaterial
        size={0.15}
        vertexColors
        transparent
        opacity={0.8}
        sizeAttenuation={true}
      />
    </points>
  )
}

function DriftOverlay({ analysis }) {
  const { calibration, environment, preprocessing, riskLevel, overallScore } = analysis

  const riskColors = {
    low: COLORS.match,
    medium: COLORS.warning,
    high: COLORS.drift
  }

  return (
    <div style={styles.overlay}>
      <div style={{...styles.overlayCard, borderColor: riskColors[riskLevel]}}>
        <div style={styles.overlayHeader}>
          <h3 style={styles.overlayTitle}>Drift Analysis</h3>
          <div style={{...styles.riskBadge, background: riskColors[riskLevel]}}>
            {riskLevel.toUpperCase()}
          </div>
        </div>

        <div style={styles.driftScore}>
          <div style={styles.scoreLabel}>Overall Drift Score</div>
          <div style={{...styles.scoreValue, color: riskColors[riskLevel]}}>
            {overallScore.toFixed(2)}
          </div>
        </div>

        <div style={styles.driftDetails}>
          <DriftMetric
            label="Calibration Drift"
            value={`${calibration.magnitude.toFixed(2)}°`}
            critical={calibration.isCritical}
            details={`Pitch: ${calibration.pitch.toFixed(2)}° | Yaw: ${calibration.yaw.toFixed(2)}°`}
          />
          <DriftMetric
            label="Environmental"
            value={environment.overall.toFixed(1)}
            critical={environment.isCritical}
            details={`Traffic: ${environment.traffic} | Lighting: ${environment.lighting}`}
          />
          <DriftMetric
            label="Preprocessing"
            value={preprocessing.overall.toFixed(1)}
            critical={preprocessing.isCritical}
            details={preprocessing.changes.join(' | ')}
          />
        </div>
      </div>
    </div>
  )
}

function DriftMetric({ label, value, critical, details }) {
  return (
    <div style={styles.metric}>
      <div style={styles.metricHeader}>
        <span style={styles.metricLabel}>{label}</span>
        <span style={{...styles.metricValue, color: critical ? COLORS.drift : COLORS.match}}>
          {value}
        </span>
      </div>
      {details && <div style={styles.metricDetails}>{details}</div>}
    </div>
  )
}

